from robyn import Robyn, Request, Response, status_codes

app = Robyn(__file__)

WORKSPACE_ANALYTICS_CACHE = {}

@app.get("/api/v1/workspaces/:workspace_id/realtime-analytics")
async def get_workspace_analytics(request: Request):
    if not request.identity:
        return Response(status_code=status_codes.HTTP_401_UNAUTHORIZED, description="Unauthorized", headers={})

    workspace_id = request.path_params.get("workspace_id")
    user_workspaces = request.identity.claims.get("workspaces", [])
    if workspace_id not in user_workspaces:
        return Response(status_code=status_codes.HTTP_403_FORBIDDEN, description="Forbidden: Access to workspace denied", headers={})

    if workspace_id not in WORKSPACE_ANALYTICS_CACHE:
        return Response(status_code=status_codes.HTTP_404_NOT_FOUND, description="Workspace not active", headers={})

    data = WORKSPACE_ANALYTICS_CACHE[workspace_id]
    return Response(status_code=status_codes.HTTP_200_OK, description=data, headers={"Content-Type": "application/json"})
